import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;

record InterviewPipeline(String company, LocalDate finalRoundDate, int daysToResult) {}

class DecisionTimeline {
    public static LocalDate calculateDeadline(List<InterviewPipeline> pipelines, 
                                               LocalDate offerReceivedDate) {
        // Find the latest pipeline completion date
        var latestDate = pipelines.stream()
            .map(p -> p.finalRoundDate().plusDays(p.daysToResult()))
            .max(LocalDate::compareTo)
            .orElse(offerReceivedDate);

        // Add 2 days buffer for family discussion and final review
        var yourDeadline = latestDate.plusDays(2);

        // Calculate days from offer received
        long daysNeeded = ChronoUnit.DAYS.between(offerReceivedDate, yourDeadline);

        // Cap at 10 days maximum to avoid losing the offer
        if (daysNeeded > 10) {
            yourDeadline = offerReceivedDate.plusDays(10);
        }

        return yourDeadline;
    }

    public static void main(String[] args) {
        var pipelines = List.of(
            new InterviewPipeline("Startup A", LocalDate.now().plusDays(3), 2),
            new InterviewPipeline("BigCorp", LocalDate.now().plusDays(5), 3)
        );

        var deadline = calculateDeadline(pipelines, LocalDate.now());
        System.out.println("Request deadline: " + deadline); // About 8-10 days
    }
}
