import java.util.*;
import java.util.stream.Collectors;

record Benefit(String name, int importance, boolean companyOffers) {}

class BenefitEvaluator {
    public static void main(String[] args) {
        // Define what matters to you as a fresher (1-10 scale)
        var benefits = List.of(
            new Benefit("Mentorship Program", 10, true),
            new Benefit("Learning Budget", 9, true),
            new Benefit("Production System Access", 9, false),
            new Benefit("Health Insurance", 8, true),
            new Benefit("Work-Life Balance", 8, true),
            new Benefit("Remote Work Days", 6, false),
            new Benefit("Free Snacks", 2, true)
        );

        // Calculate alignment score
        int totalPossible = benefits.stream()
            .mapToInt(Benefit::importance)
            .sum();

        int companyScore = benefits.stream()
            .filter(Benefit::companyOffers)
            .mapToInt(Benefit::importance)
            .sum();

        double alignmentPercent = (companyScore * 100.0) / totalPossible;

        System.out.printf("Company offers %.0f%% of what you value%n", alignmentPercent);

        // List missing high-priority benefits
        var missing = benefits.stream()
            .filter(b -> !b.companyOffers() && b.importance() >= 8)
            .map(Benefit::name)
            .collect(Collectors.joining(", "));

        if (!missing.isEmpty()) {
            System.out.println("Missing critical benefits: " + missing);
        }
    }
}
