record JobOffer(String company, int baseSalary, 
                boolean hasMentorship, int learningBudget,
                boolean modernTechStack, boolean remoteOption) {

    int calculateTotalValue() {
        int value = baseSalary / 1000; // normalize salary

        if (hasMentorship) value += 50; // mentorship worth ~50k
        value += learningBudget / 1000; // learning budget contribution
        if (modernTechStack) value += 30; // modern stack premium
        if (remoteOption) value += 20; // flexibility value

        return value;
    }
}

var offerA = new JobOffer("Company A", 500000, true, 50000, 
                          true, false);
var offerB = new JobOffer("Company B", 550000, false, 0, 
                          false, true);

System.out.println("Offer A total value: " + offerA.calculateTotalValue());
System.out.println("Offer B total value: " + offerB.calculateTotalValue());
// Offer A might win despite lower base salary
