import java.util.*;

record SalaryData(String source, String city, double minLPA, double maxLPA) {}

class SalaryResearch {
    public static void main(String[] args) {
        // Collect data points from multiple sources
        var dataPoints = List.of(
            new SalaryData("Glassdoor", "Bangalore", 3.5, 6.0),
            new SalaryData("AmbitionBox", "Bangalore", 4.0, 7.0),
            new SalaryData("Levels.fyi", "Bangalore", 5.0, 8.5)
        );

        // Calculate average range across sources
        double avgMin = dataPoints.stream()
            .mapto-double(SalaryData::minLPA)
            .average()
            .orElse(0.0);

        double avgMax = dataPoints.stream()
            .mapto-double(SalaryData::maxLPA)
            .average()
            .orElse(0.0);

        // Your expected range with 10% buffer
        System.out.printf("Market range: %.1f - %.1f LPA%n", avgMin, avgMax);
        System.out.printf("Your ask: %.1f - %.1f LPA%n", avgMin * 0.9, avgMax * 1.1);
    }
}
