import java.util.*;

record Offer(String company, double salary, double bonus, String benefits) {}

class OfferEvaluator {
    private final double myMinimum = 5.0; // Your floor in LPA

    public String evaluate(Offer offer) {
        double totalComp = offer.salary() + offer.bonus();

        // Check if total compensation meets your minimum
        if (totalComp >= myMinimum) {
            return "ACCEPTABLE - Total comp meets minimum";
        }

        // Calculate the gap
        double gap = myMinimum - totalComp;
        double gapPercent = (gap / myMinimum) * 100;

        // Decision logic: negotiate if gap is under 15%
        if (gapPercent < 15) {
            return String.format("NEGOTIATE - Gap is %.1f%%, try for %.1f LPA", 
                gapPercent, myMinimum);
        } else {
            return String.format("DECLINE - Gap is %.1f%%, too far from target", 
                gapPercent);
        }
    }

    public static void main(String[] args) {
        var evaluator = new OfferEvaluator();
        var offer = new Offer("TechCorp", 4.5, 0.3, "Health + Learning");
        System.out.println(evaluator.evaluate(offer)); // NEGOTIATE
    }
}
