record Offer(String company, int salary, int learningScore, 
             int mentorshipScore, int techStackScore) {
    int totalValue() {
        // Early career: weight learning 3x, mentorship 2x
        return learningScore * 3 + mentorshipScore * 2 + 
               techStackScore * 2 + (salary / 10000);
    }
}

var companyA = new Offer("Company A", 500000, 6, 5, 7);
var companyB = new Offer("Company B", 450000, 9, 8, 9);

if (companyB.totalValue() > companyA.totalValue()) {
    System.out.println("Company B offers better long-term value");
    System.out.println("Reason: Learning (" + companyB.learningScore() + 
                       ") and mentorship (" + companyB.mentorshipScore() + 
                       ") outweigh 10% salary gap");
}
